INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 6, 'theory', 'Quiz: JOIN');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 6, 0, 'Tables of 4 and 3 rows are joined with no condition (CROSS JOIN). How many rows are in the result?', '["3", "4", "7", "12"]', 3, 'Cartesian product: 4 × 3 = 12 pairs. A join condition is needed to keep only the meaningful ones.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 6, 1, 'Which customers appear in the result of INNER JOIN of customers with orders on customer_id?', '["All customers", "Only customers who have at least one order", "Only customers without orders", "Customers and orders without customers"]', 1, 'INNER JOIN keeps only the pairs for which the condition is true; a customer without orders has no pair and disappears.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 6, 2, 'How do you find customers who have no orders at all?', '["INNER JOIN … WHERE o.id IS NULL", "LEFT JOIN … WHERE o.id IS NULL", "RIGHT JOIN … WHERE c.id IS NULL", "LEFT JOIN … WHERE o.id = 0"]', 1, 'LEFT JOIN keeps all customers; those with no orders have NULL in the order columns, and the IS NULL condition keeps exactly them.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 6, 3, 'Why can WHERE o.status = ''paid'' after a LEFT JOIN "break" the join?', '["It is a syntax error", "Customers without orders have status = NULL, the condition fails, and they disappear", "WHERE ignores the right table", "LEFT JOIN cannot be combined with WHERE"]', 1, 'A condition on the right table in WHERE discards rows with NULL, turning the LEFT JOIN into an inner one. Move the condition to ON.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 6, 4, 'An order costing 100 has 3 lines. What is SUM(o.total) after joining with the lines?', '["100", "300", "33.3", "3"]', 1, 'A one-to-many join multiplies the order row: total is repeated three times. Aggregate before joining, or count over unique orders.');
